  <el-drawer class="kb-drawer" v-model="reportOpen" :title="reportTitle+' · 学习记录'" size="min(1050px,96vw)"><div class="counts"><div v-for="s in ['unread','read','learned']" :key="s"><span>{{readStates[s]}}</span><strong>{{reportRows.filter(r=>r.status===s).length}}</strong></div></div><el-input v-model="reportSearch" clearable placeholder="搜索员工、岗位或门店" class="space"/><el-table :data="reportRows.filter(r=>!reportSearch||[r.name,...r.positions,...r.stores.map(s=>s.store_name)].join(' ').includes(reportSearch))"><el-table-column prop="name" label="员工"/><el-table-column label="岗位"><template #default="{row}">{{row.positions.join('、')}}</template></el-table-column><el-table-column label="负责门店"><template #default="{row}"><span :title="row.stores.map(s=>s.store_name).join('、')">{{row.stores.length===1?row.stores[0].store_name:row.stores.length+'个门店'}}</span></template></el-table-column><el-table-column prop="home_store_name" label="归属门店"/><el-table-column prop="learning_store_name" label="学习门店"/><el-table-column prop="employment_status" label="在职状态" width="110"/><el-table-column label="状态" width="85"><template #default="{row}">{{readStates[row.status]}}</template></el-table-column><el-table-column label="阅读时间"><template #default="{row}">{{time(row.record?.first_read_at)}}</template></el-table-column><el-table-column label="学习确认时间"><template #default="{row}">{{time(row.record?.learned_at)}}</template></el-table-column><template #empty><div class="record-empty"><el-icon><User /></el-icon><h3>{{reportSearch?'没有找到对应员工':'暂无可统计的学习人员'}}</h3><p>{{reportSearch?'试试其他姓名、岗位或门店。':'请先检查资料的阅读岗位和适用门店设置。'}}</p></div></template></el-table></el-drawer>
