prevent="saveCategory"><el-form-item label="分类名称" required><el-input v-model="categoryForm.name" maxlength="30" show-word-limit placeholder="例如：门店运营"/></el-form-item><el-form-item label="展示顺序"><el-input-number v-model="categoryForm.sort_order" :min="0" :max="999" :step="1" controls-position="right"/><p class="field-help">数字越小，分类越靠前。</p></el-form-item><el-button class="category-submit" type="primary" native-type="submit" :icon="categoryForm.id?Check:Plus" :loading="busy">{{categoryForm.id?'保存修改':'新增分类'}}</el-button><el-button v-if="categoryForm.id" class="cancel-edit" @click="categoryForm={name:'',sort_order:nextCategoryOrder}">取消编辑</el-button></el-form></aside></div><template #footer><div class="dialog-footer"><span><el-icon><InfoFilled /></el-icon> 已有资料或历史版本的分类将保留，避免记录失去归属。</span><el-button @click="categoriesOpen=false">完成</el-button></div></template></el-dialog>
